      "content": "{\n  \"name\": \"@openviking/dsh-memory-plugin\",\n  \"version\": \"0.5.31\",\n  \"description\": \"OpenViking memory and context bundle for DeepSeek Harness\",\n  \"icon\": \"./icon.svg\",\n  \"type\": \"module\",\n  \"main\": \"index.mjs\",\n  \"exports\": {\n    \".\": \"./index.mjs\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"icon.svg\",\n    \"index.mjs\",\n    \"client.mjs\",\n    \"config.mjs\",\n    \"capture.mjs\",\n    \"lifecycle.mjs\",\n    \"mcp.mjs\",\n    \"mcp-env.mjs\",\n    \"runtime.mjs\",\n    \"session-id.mjs\",\n    \"skills.mjs\",\n    \"uri-guard.mjs\",\n    \"servers/\",\n    \"shared/\",\n    \"skills/\",\n    \"locale/\",\n    \"docs/\",\n    \"cordis.patch.yml\",\n    \"README.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"scripts\": {\n    \"prepack\": \"node ../memory-plugin-shared/sync.mjs\",\n    \"check\": \"for f in *.mjs shared/*.mjs; do node --check \\\"$f\\\" || exit 1; done && npm run check:version\",\n    \"check:version\": \"node --input-type=module -e \\\"import {readFileSync} from 'node:fs'; const {PLUGIN_VERSION} = await import('./config.mjs'); const v = JSON.parse(readFileSync('package.json','utf8')).version; if (PLUGIN_VERSION !== v) throw new Error('PLUGIN_VERSION ' + PLUGIN_VERSION + ' does not match package.json version ' + v);\\\"\",\n    \"test\": \"node --test *.test.mjs\",\n    \"prepublishOnly\": \"npm run prepack && npm run check && npm test\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/dsh-llm\": \">=0.1.0-rc.6 <1.0.0-0\",\n    \"@deepseek-ai/dsh-mcp-client\": \">=0.1.0-rc.6 <1.0.0-0\",\n    \"@deepseek-ai/dsh-skill-filesystem\": \">=0.1.0-rc.6 <1.0.0-0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-llm\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-mcp-client\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-skill-filesystem\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.0-rc.6\",\n    \"semver\": \"7.8.5\"\n  },\n  \"overrides\": {\n    \"@deepseek-ai/dsh-agent\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-attachment\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-brand\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-code-runtime\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-invariants\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-mcp-client\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-scope\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-skill-filesystem\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-timeout\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.1.0-rc.6\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/volcengine/OpenViking.git\",\n    \"directory\": \"examples/dsh-memory-plugin\"\n  },\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"openviking\",\n    \"memory\",\n    \"context\",\n    \"auto-recall\",\n    \"auto-capture\"\n  ],\n  \"license\": \"Apache-2.0\"\n}\n"
    },
